
const params=new URLSearchParams(location.search),id=params.get('id');
const all=window.learningCatalog.flatMap((module,moduleIndex)=>module.groups.flatMap(group=>group.items.map(item=>({item,group,module,moduleIndex}))));
const selected=all.find(x=>x.item.id===id);let dark=params.get('theme')==='dark';
function courseUrl(id){return 'lesson.html?id='+encodeURIComponent(id)+(dark?'&theme=dark':'')}
function syncTheme(){document.body.classList.toggle('dark',dark);document.querySelector('#theme').textContent=dark?'☀':'◐';document.querySelector('#theme').setAttribute('aria-label',dark?'切换亮色主题':'切换暗色主题');document.querySelectorAll('[data-lesson-id]').forEach(a=>a.href=courseUrl(a.dataset.lessonId));const url='index.html'+(dark?'?theme=dark':'')+'#module'+(selected?.moduleIndex||0);document.querySelector('#back').href=url;document.querySelector('#module-link').href=url}
document.querySelector('#theme').onclick=()=>{dark=!dark;syncTheme()};
function setResource(format){const choices={ppt:['▣','PPT 课件制作中','此课程尚未配置可学习的幻灯片。后续将在这里逐页学习，当前不提供演示文件。'],article:['▤','图文正文暂未开放','课程介绍和计划练习可查看；完整正文、配图与PDF资料仍在整理，尚未开放阅读或下载。'],video:['▷','教学视频筹备中','此课程尚未配置已发布的教学视频。后续将在这里观看讲解与带领示范。']};const text=choices[format]||choices.article;document.querySelectorAll('[role=tab]').forEach(b=>{const active=b.dataset.format===format;b.setAttribute('aria-selected',active);b.tabIndex=active?0:-1});const panel=document.querySelector('#resource-panel');panel.dataset.format=format;panel.setAttribute('aria-labelledby','tab-'+format);document.querySelector('.resource-symbol').textContent=text[0];document.querySelector('#resource-title').textContent=text[1];document.querySelector('#resource-description').textContent=text[2];}
const tabs=[...document.querySelectorAll('[role=tab]')];tabs.forEach((tab,i)=>{tab.onclick=()=>setResource(tab.dataset.format);tab.onkeydown=e=>{let n;if(e.key==='ArrowRight')n=(i+1)%3;if(e.key==='ArrowLeft')n=(i+2)%3;if(e.key==='Home')n=0;if(e.key==='End')n=2;if(n!==undefined){e.preventDefault();tabs[n].focus();setResource(tabs[n].dataset.format)}}});
if(!selected){document.querySelector('.study-layout').hidden=true;document.querySelector('.study-layout').style.display='none';document.querySelector('.not-found').hidden=false;document.querySelector('#lesson-title').textContent='课程不存在';document.querySelector('#course-kind').textContent='请选择目录中的课程'}else{
 const {item,group,module,moduleIndex}=selected;document.title=item.title+' · 守望者学习';document.querySelector('#lesson-title').textContent=item.title;document.querySelector('#module-link').textContent=String(moduleIndex).padStart(2,'0')+' '+module.title;document.querySelector('#group-name').textContent=group.title;document.querySelector('#course-kind').textContent=moduleIndex===0?'基础资料 · 阅读未开放':'课程规划 · 内容筹备中';document.querySelector('#lesson-objective').textContent=module.familyRole;document.querySelector('#objective-detail').textContent=item.objective;document.querySelector('#practice-detail').textContent=item.practice;document.querySelector('#planning-note').textContent=moduleIndex===0?'原始资料已完成本地归档，尚未发布至学习网站。':'以上为教学设计目标与计划练习，不代表课程内容已制作或发布。';
 function link(id,title){const a=document.createElement('a');a.dataset.lessonId=id;a.href=courseUrl(id);a.textContent=title;return a}
 group.items.forEach((entry,index)=>{const li=document.createElement('li'),a=link(entry.id,'');const num=document.createElement('span');num.textContent=String(index+1).padStart(2,'0');const name=document.createElement('span');name.textContent=entry.title;a.append(num,name);if(entry.id===id)a.setAttribute('aria-current','page');li.append(a);document.querySelector('#chapter-lessons').append(li)});
 (item.sourceIds||[]).filter(source=>source!==id).forEach(source=>{const found=all.find(x=>x.item.id===source);if(found){const li=document.createElement('li');li.append(link(source,found.item.title));document.querySelector('#references').append(li)}});if(!document.querySelector('#references').children.length)document.querySelector('.reference-section').hidden=true;
 const index=all.findIndex(x=>x.item.id===id);[['#previous',all[index-1]],['#next',all[index+1]]].forEach(([selector,next])=>{if(next){const a=document.querySelector(selector);a.dataset.lessonId=next.item.id;a.href=courseUrl(next.item.id);a.hidden=false}});setResource(item.format||'article');
}
syncTheme();
